steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: <TOKEN>" -d '{"query":"{ __schema { types { name kind inputFields { name } fields { name } } } }"}' | python3 -c "
import sys, json
d = json.load(sys.stdin)
for t in d['data']['__schema']['types']:
    fields = (t.get('inputFields') or []) + (t.get('fields') or [])
    for f in fields:
        n = f.get('name','')
        if 'pdate' in n or 'ime' in n and n not in ('time',):
            print(t['name'], '->', n)
" 2>/dev/null | sort -u | head -60
